import { buildWaves } from "../lib/spec-orchestrator.js";
import {
  type ApiError,
  type ExtensionAPI,
  type ExtensionCommandContext,
  apiFetchJson,
  apiFetchText,
  decodeOutputLines,
  normalizeKey,
  notify,
  pad,
  resolveWorkspace,
  timeAgo,
  truncate,
} from "./shared.js";

type RunStatus =
  | "queued"
  | "running"
  | "paused"
  | "cancelling"
  | "cancelled"
  | "passed"
  | "failed"
  | "partial_failure"
  | "done"
  | "skipped"
  | "pass"
  | "fail"
  | "pending"
  | "retrying"
  | "merged"
  | string;

type StorySpec = {
  id: string;
  title: string;
  dependsOn?: string[];
  agent?: string;
  suggestedSkills?: string[];
  reroute?: { fromEngine: string; toEngine: string; reason: string };
};

type RunStory = {
  story_id: string;
  status: string;
  retries?: number;
  started_at?: string | null;
  finished_at?: string | null;
  elapsed_seconds?: number | null;
  model_used?: string | null;
  input_tokens?: number | null;
  output_tokens?: number | null;
  cost_usd?: number | null;
};

type StoryTokenBreakdown = {
  storyId: string;
  status: string;
  inputTokens: number;
  outputTokens: number;
  modelUsed: string | null;
  costUsd: number;
};

type RunStateStory = {
  storyId: string;
  retries?: number;
  elapsedMs?: number;
  failReason?: string;
};

type RunStateDecision = {
  storyId: string;
  timestamp: string;
  type: string;
  description: string;
};

type RunState = {
  specId: string;
  runId: number;
  startedAt: string;
  lastUpdatedAt: string;
  completedStories: RunStateStory[];
  failedStories: RunStateStory[];
  skippedStories: RunStateStory[];
  currentStory: string | null;
  decisions: RunStateDecision[];
  resumedFromStory?: string | null;
};

type ContextComparison = {
  predicted: Record<string, { totalTokens: number; injectedFiles: string[] }>;
  actual: Record<string, { contextFiles: string[] }>;
};

type RunPayload = {
  run: {
    id: number;
    status: RunStatus;
    spec_path?: string;
    started_at?: string;
    finished_at?: string | null;
    agent_model?: string | null;
    agent_type?: string | null;
    summary?: string | null;
    merge_status?: string | null;
    queue_position?: number | null;
    workspace_id?: string | number;
  };
  stories?: RunStory[];
  specStories?: StorySpec[];
  specModel?: string | null;
  agentType?: string | null;
  agentModel?: string | null;
  worktreePath?: string | null;
  branchName?: string | null;
  includeGraph?: boolean;
  tokenSummary?: {
    inputTokens: number;
    outputTokens: number;
    totalCostUsd: number;
  };
  storyTokenBreakdown?: StoryTokenBreakdown[];
  runState?: RunState | null;
  contextComparison?: ContextComparison | null;
};

type RunListItem = {
  id: number;
  status: RunStatus;
  spec_path?: string;
  started_at?: string;
};

type RunListPayload = {
  items?: RunListItem[];
};

type StoryOutputPayload = {
  storyId: string;
  runId: number;
  status: string;
  retries: number;
  failureReason?: string | null;
  failureAttempts?: number | null;
  blockedBy?: string[] | null;
  output?: string[];
  lineCount?: number;
};

type RetryResponse = {
  ok?: boolean;
  queued?: boolean;
  jobId?: string;
  runId?: number | string;
};

type StoryView = {
  id: string;
  title: string;
  dependsOn: string[];
  status: RunStatus;
  agent?: string;
  suggestedSkills: string[];
  reroute?: { fromEngine: string; toEngine: string; reason: string };
  retries: number;
  startedAt?: string | null;
  finishedAt?: string | null;
  elapsedSeconds?: number | null;
  failureReason?: string | null;
  modelUsed?: string | null;
  inputTokens: number;
  outputTokens: number;
  costUsd: number;
  predictedContextTokens: number;
  predictedContextFiles: string[];
  actualContextFiles: string[];
};

type StoryCollection = {
  stories: StoryView[];
  waves: StoryView[][];
};

type Pane = "output" | "story" | "run" | "events" | "log" | "commits";

type RunCommit = {
  sha: string;
  message: string;
  date: string;
  author: string;
};

const RUN_VIEW_STATUS_ID = "rorca.run-cockpit";

type RunCommitsPayload = {
  commits?: RunCommit[];
  branchName?: string | null;
};

function normalizeStatus(status: string | undefined): RunStatus {
  switch (status) {
    case "pass":
    case "passed":
      return "passed";
    case "fail":
    case "failed":
      return "failed";
    case "skip":
    case "skipped":
      return "skipped";
    default:
      return status ?? "pending";
  }
}

function statusIcon(status: string | undefined): string {
  switch (normalizeStatus(status)) {
    case "queued":
      return "◌";
    case "running":
      return "↻";
    case "paused":
      return "⏸";
    case "cancelling":
      return "!";
    case "cancelled":
      return "⊘";
    case "passed":
    case "done":
    case "merged":
      return "✓";
    case "failed":
    case "partial_failure":
      return "✗";
    case "skipped":
      return "↷";
    case "retrying":
      return "↺";
    default:
      return "·";
  }
}

function formatStatus(status: string | undefined): string {
  return normalizeStatus(status).replace(/_/g, " ");
}

function formatTokens(value: number | null | undefined): string {
  const amount = value ?? 0;
  if (amount >= 1_000_000) {
    return `${(amount / 1_000_000).toFixed(1)}M`;
  }
  if (amount >= 1_000) {
    return `${(amount / 1_000).toFixed(1)}k`;
  }
  return String(amount);
}

function formatCurrency(value: number | null | undefined): string {
  return `$${(value ?? 0).toFixed(3)}`;
}

function formatDuration(seconds: number | null | undefined): string {
  if (seconds == null || !Number.isFinite(seconds)) {
    return "unknown";
  }

  if (seconds < 60) {
    return `${Math.max(0, Math.floor(seconds))}s`;
  }

  const minutes = Math.floor(seconds / 60);
  if (minutes < 60) {
    return `${minutes}m ${Math.floor(seconds % 60)}s`;
  }

  const hours = Math.floor(minutes / 60);
  return `${hours}h ${minutes % 60}m`;
}

function formatList(values: string[], empty = "none"): string {
  return values.length > 0 ? values.join(", ") : empty;
}

function extractSpecSlug(specPath: string | undefined): string {
  const fileName = specPath?.split("/").pop() ?? "unknown";
  return fileName.endsWith(".json") ? fileName.slice(0, -5) : fileName;
}

function countStatuses(stories: StoryView[]): Map<string, number> {
  const counts = new Map<string, number>();
  for (const story of stories) {
    const key = normalizeStatus(story.status);
    counts.set(key, (counts.get(key) ?? 0) + 1);
  }
  return counts;
}

function getStoryStateStatuses(runState: RunState | null | undefined) {
  const completed = new Set((runState?.completedStories ?? []).map((story) => story.storyId));
  const failed = new Set((runState?.failedStories ?? []).map((story) => story.storyId));
  const skipped = new Set((runState?.skippedStories ?? []).map((story) => story.storyId));
  const current = runState?.currentStory ?? null;
  const failureReasons = new Map((runState?.failedStories ?? []).map((story) => [story.storyId, story.failReason ?? null] as const));

  return { completed, failed, skipped, current, failureReasons };
}

function buildStories(payload: RunPayload): StoryCollection {
  const resultById = new Map<string, RunStory>();
  for (const story of payload.stories ?? []) {
    resultById.set(story.story_id, story);
  }

  const tokensById = new Map<string, StoryTokenBreakdown>();
  for (const token of payload.storyTokenBreakdown ?? []) {
    tokensById.set(token.storyId, token);
  }

  const predictedContextById = new Map(Object.entries(payload.contextComparison?.predicted ?? {}));
  const actualContextById = new Map(Object.entries(payload.contextComparison?.actual ?? {}));
  const stateStatus = getStoryStateStatuses(payload.runState);
  const stories: StoryView[] = [];
  const seen = new Set<string>();

  const inferStatus = (storyId: string, resultStatus?: string): RunStatus => {
    if (resultStatus) {
      return normalizeStatus(resultStatus);
    }
    if (stateStatus.current === storyId) {
      return "running";
    }
    if (stateStatus.failed.has(storyId)) {
      return "failed";
    }
    if (stateStatus.skipped.has(storyId)) {
      return "skipped";
    }
    if (stateStatus.completed.has(storyId)) {
      return "passed";
    }
    return "pending";
  };

  for (const specStory of payload.specStories ?? []) {
    const result = resultById.get(specStory.id);
    const token = tokensById.get(specStory.id);
    const predictedContext = predictedContextById.get(specStory.id);
    const actualContext = actualContextById.get(specStory.id);
    stories.push({
      id: specStory.id,
      title: specStory.title,
      dependsOn: specStory.dependsOn ?? [],
      status: inferStatus(specStory.id, result?.status),
      agent: specStory.agent,
      suggestedSkills: specStory.suggestedSkills ?? [],
      reroute: specStory.reroute,
      retries: result?.retries ?? 0,
      startedAt: result?.started_at,
      finishedAt: result?.finished_at,
      elapsedSeconds: result?.elapsed_seconds ?? null,
      failureReason: stateStatus.failureReasons.get(specStory.id) ?? null,
      modelUsed: result?.model_used ?? token?.modelUsed ?? null,
      inputTokens: token?.inputTokens ?? result?.input_tokens ?? 0,
      outputTokens: token?.outputTokens ?? result?.output_tokens ?? 0,
      costUsd: token?.costUsd ?? result?.cost_usd ?? 0,
      predictedContextTokens: predictedContext?.totalTokens ?? 0,
      predictedContextFiles: predictedContext?.injectedFiles ?? [],
      actualContextFiles: actualContext?.contextFiles ?? [],
    });
    seen.add(specStory.id);
  }

  for (const result of payload.stories ?? []) {
    if (seen.has(result.story_id)) {
      continue;
    }
    const token = tokensById.get(result.story_id);
    const predictedContext = predictedContextById.get(result.story_id);
    const actualContext = actualContextById.get(result.story_id);
    stories.push({
      id: result.story_id,
      title: result.story_id,
      dependsOn: [],
      status: inferStatus(result.story_id, result.status),
      suggestedSkills: [],
      retries: result.retries ?? 0,
      startedAt: result.started_at,
      finishedAt: result.finished_at,
      elapsedSeconds: result.elapsed_seconds ?? null,
      failureReason: stateStatus.failureReasons.get(result.story_id) ?? null,
      modelUsed: result.model_used ?? token?.modelUsed ?? null,
      inputTokens: token?.inputTokens ?? result.input_tokens ?? 0,
      outputTokens: token?.outputTokens ?? result.output_tokens ?? 0,
      costUsd: token?.costUsd ?? result.cost_usd ?? 0,
      predictedContextTokens: predictedContext?.totalTokens ?? 0,
      predictedContextFiles: predictedContext?.injectedFiles ?? [],
      actualContextFiles: actualContext?.contextFiles ?? [],
    });
  }

  const byId = new Map(stories.map((story) => [story.id, story] as const));
  const waves: StoryView[][] = [];

  if ((payload.specStories ?? []).length > 0) {
    try {
      const computed = buildWaves(
        (payload.specStories ?? []).map((story) => ({
          id: story.id,
          title: story.title,
          description: story.title,
          acceptanceCriteria: [],
          dependsOn: story.dependsOn ?? [],
        })),
      );

      for (const wave of computed) {
        waves.push(wave.map((story) => byId.get(story.id)).filter((story): story is StoryView => Boolean(story)));
      }
    } catch {
      // Fall back to a flat story list when dependency metadata is malformed.
    }
  }

  if (waves.length === 0 && stories.length > 0) {
    waves.push([...stories]);
  }

  const seenInWaves = new Set(waves.flatMap((wave) => wave.map((story) => story.id)));
  const orphanStories = stories.filter((story) => !seenInWaves.has(story.id));
  if (orphanStories.length > 0) {
    waves.push(orphanStories);
  }

  return { stories, waves };
}

function chooseStoryId(stories: StoryView[], currentStoryId: string | null): string | null {
  if (stories.length === 0) {
    return null;
  }
  if (currentStoryId && stories.some((story) => story.id === currentStoryId)) {
    return currentStoryId;
  }

  const preferred =
    stories.find((story) => normalizeStatus(story.status) === "running") ??
    stories.find((story) => normalizeStatus(story.status) === "failed") ??
    stories.find((story) => normalizeStatus(story.status) === "queued") ??
    stories[0];

  return preferred?.id ?? null;
}

function wrapSimple(text: string, width: number): string[] {
  const safeWidth = Math.max(10, width);
  const lines: string[] = [];
  const normalized = text.replace(/\s+/g, " ").trim();
  if (!normalized) {
    return [""];
  }

  let remaining = normalized;
  while (remaining.length > safeWidth) {
    const slice = remaining.slice(0, safeWidth + 1);
    const breakAt = Math.max(slice.lastIndexOf(" "), safeWidth - 8);
    const next = remaining.slice(0, breakAt).trimEnd();
    lines.push(next);
    remaining = remaining.slice(Math.max(1, breakAt)).trimStart();
  }
  lines.push(remaining);
  return lines;
}

function renderBodyColumns(leftLines: string[], rightLines: string[], width: number): string[] {
  const safeWidth = Math.max(80, width);
  const leftWidth = Math.max(28, Math.floor(safeWidth * 0.43));
  const rightWidth = Math.max(28, safeWidth - leftWidth - 3);
  const rows = Math.max(leftLines.length, rightLines.length);
  const lines: string[] = [];

  for (let index = 0; index < rows; index += 1) {
    const left = pad(truncate(leftLines[index] ?? "", leftWidth), leftWidth);
    const right = truncate(rightLines[index] ?? "", rightWidth);
    lines.push(`${left} │ ${right}`);
  }

  return lines;
}

function isTerminalStoryStatus(status: string | undefined): boolean {
  const normalized = normalizeStatus(status);
  return normalized === "passed" || normalized === "failed" || normalized === "skipped" || normalized === "cancelled" || normalized === "done";
}

function summarizeWaveProgress(waves: StoryView[]): { total: number; done: number; running: number; failed: number; pending: number } {
  return waves.reduce(
    (summary, story) => {
      summary.total += 1;
      const normalized = normalizeStatus(story.status);
      if (isTerminalStoryStatus(normalized)) {
        summary.done += 1;
      }
      if (normalized === "running") {
        summary.running += 1;
      }
      if (normalized === "failed") {
        summary.failed += 1;
      }
      if (normalized === "pending" || normalized === "queued") {
        summary.pending += 1;
      }
      return summary;
    },
    { total: 0, done: 0, running: 0, failed: 0, pending: 0 },
  );
}

function isSatisfiedDependencyStatus(status: string | undefined): boolean {
  const normalized = normalizeStatus(status);
  return normalized === "passed" || normalized === "done" || normalized === "merged" || normalized === "skipped";
}

function countCompletedDependencies(story: StoryView, stories: StoryView[]): { done: number; total: number } {
  if (story.dependsOn.length === 0) {
    return { done: 0, total: 0 };
  }

  const byId = new Map(stories.map((candidate) => [candidate.id, candidate] as const));
  let done = 0;
  for (const dependencyId of story.dependsOn) {
    const dependency = byId.get(dependencyId);
    if (dependency && isSatisfiedDependencyStatus(dependency.status)) {
      done += 1;
    }
  }

  return { done, total: story.dependsOn.length };
}

function isStoryReady(story: StoryView, stories: StoryView[]): boolean {
  const status = normalizeStatus(story.status);
  if (status !== "pending" && status !== "queued") {
    return false;
  }

  const dependencyProgress = countCompletedDependencies(story, stories);
  return dependencyProgress.done === dependencyProgress.total;
}

function findDependentStories(storyId: string, stories: StoryView[]): StoryView[] {
  return stories.filter((candidate) => candidate.dependsOn.includes(storyId));
}

function findActiveWave(waves: StoryView[][]): { index: number; stories: StoryView[] } | null {
  for (let index = 0; index < waves.length; index += 1) {
    const wave = waves[index] ?? [];
    if (wave.some((story) => !isTerminalStoryStatus(story.status))) {
      return { index, stories: wave };
    }
  }

  if (waves.length === 0) {
    return null;
  }

  return { index: waves.length - 1, stories: waves[waves.length - 1] ?? [] };
}

function renderStoryList(stories: StoryView[], waves: StoryView[][], selectedStoryId: string | null, width: number): string[] {
  const lines: string[] = [truncate(`Stories (${stories.length})`, width), ""];

  const dependencyProgressByStoryId = new Map(
    stories.map((story) => [story.id, countCompletedDependencies(story, stories)] as const),
  );

  if (stories.length === 0) {
    lines.push("No story activity has been recorded for this run yet.");
    return lines;
  }

  waves.forEach((wave, waveIndex) => {
    const counts = countStatuses(wave);
    const summary = [
      `${counts.get("running") ?? 0} running`,
      `${counts.get("passed") ?? 0} passed`,
      `${counts.get("failed") ?? 0} failed`,
    ].join(" • ");
    lines.push(truncate(`Wave ${waveIndex + 1} — ${summary}`, width));
    for (const story of wave) {
      const marker = story.id === selectedStoryId ? ">" : " ";
      const retryBadge = story.retries > 0 ? ` • retry ${story.retries}` : "";
      const dependencyProgress = dependencyProgressByStoryId.get(story.id) ?? { done: 0, total: 0 };
      const blockedBadge =
        dependencyProgress.total > 0 && (normalizeStatus(story.status) === "pending" || normalizeStatus(story.status) === "queued")
          ? ` • deps ${dependencyProgress.done}/${dependencyProgress.total}`
          : "";
      const headline = `${marker} ${statusIcon(story.status)} ${story.id}${retryBadge}${blockedBadge}`;
      lines.push(truncate(headline, width));
      lines.push(truncate(`   ${story.title}`, width));
      if (story.failureReason) {
        lines.push(truncate(`   Failure: ${story.failureReason}`, width));
      }
    }
    lines.push("");
  });

  return lines;
}

function buildOutputPane(story: StoryView | undefined, output: StoryOutputPayload | null, outputError: string | null, width: number): string[] {
  const lines: string[] = [truncate(`Output${story ? ` — ${story.id}` : ""}`, width), ""];

  if (!story) {
    lines.push("Select a story to inspect its live output.");
    return lines;
  }

  lines.push(truncate(story.title, width));
  lines.push(truncate(`Status ${formatStatus(story.status)} • retries ${story.retries} • model ${story.modelUsed || "auto"}`, width));
  if (output?.lineCount != null) {
    lines.push(truncate(`Captured lines: ${output.lineCount}`, width));
  }
  if (output?.failureAttempts != null) {
    lines.push(truncate(`Failed attempts: ${output.failureAttempts}`, width));
  }

  if (output?.failureReason) {
    lines.push(truncate(`Failure: ${output.failureReason}`, width));
  }
  if ((output?.blockedBy ?? []).length > 0) {
    lines.push(truncate(`Blocked by: ${formatList(output?.blockedBy ?? [])}`, width));
  }

  lines.push("");

  if (outputError) {
    lines.push(truncate(outputError, width));
    return lines;
  }

  const outputLines = decodeOutputLines(output).slice(-14);
  if (outputLines.length > 0 && output?.lineCount && output.lineCount > outputLines.length) {
    lines.push(truncate(`Showing last ${outputLines.length} of ${output.lineCount} lines`, width));
    lines.push("");
  }

  if (outputLines.length === 0) {
    lines.push("No captured story output yet.");
  } else {
    for (const line of outputLines) {
      lines.push(truncate(line, width));
    }
  }

  return lines;
}

function buildStoryPane(
  story: StoryView | undefined,
  stories: StoryView[],
  runState: RunState | null | undefined,
  output: StoryOutputPayload | null,
  width: number,
): string[] {
  const lines: string[] = [truncate(`Story${story ? ` — ${story.id}` : ""}`, width), ""];

  if (!story) {
    lines.push("Select a story to inspect execution metadata.");
    return lines;
  }

  lines.push(truncate(story.title, width));
  lines.push(truncate(`Status: ${formatStatus(story.status)}`, width));
  const dependencyProgress = countCompletedDependencies(story, stories);
  const dependentStories = findDependentStories(story.id, stories);

  lines.push(truncate(`Agent: ${story.agent || story.modelUsed || "auto"}`, width));
  lines.push(truncate(`Depends on: ${formatList(story.dependsOn)}`, width));
  if (dependencyProgress.total > 0) {
    lines.push(truncate(`Dependency progress: ${dependencyProgress.done}/${dependencyProgress.total} done`, width));
  }
  lines.push(truncate(`Unblocks: ${dependentStories.length > 0 ? dependentStories.map((candidate) => candidate.id).slice(0, 3).join(", ") : "none"}${dependentStories.length > 3 ? " …" : ""}`, width));
  lines.push(truncate(`Suggested skills: ${formatList(story.suggestedSkills)}`, width));
  lines.push(truncate(`Duration: ${formatDuration(story.elapsedSeconds)}`, width));
  lines.push(truncate(`Tokens: in ${formatTokens(story.inputTokens)} • out ${formatTokens(story.outputTokens)} • ${formatCurrency(story.costUsd)}`, width));
  lines.push(truncate(`Retries: ${story.retries}${output?.failureAttempts ? ` • failed attempts ${output.failureAttempts}` : ""}`, width));

  const blockedBy = output?.blockedBy ?? [];
  if (blockedBy.length > 0) {
    lines.push(truncate(`Blocked by: ${formatList(blockedBy)}`, width));
  }

  const predictedFiles = story.predictedContextFiles;
  const actualFiles = story.actualContextFiles;
  if (predictedFiles.length > 0 || actualFiles.length > 0 || story.predictedContextTokens > 0) {
    lines.push("");
    lines.push(truncate(`Context plan: ${predictedFiles.length} files • ${formatTokens(story.predictedContextTokens)} predicted tokens`, width));
    lines.push(truncate(`Context used: ${actualFiles.length} files`, width));

    const missing = predictedFiles.filter((file) => !actualFiles.includes(file));
    const extra = actualFiles.filter((file) => !predictedFiles.includes(file));
    if (missing.length === 0 && extra.length === 0 && actualFiles.length > 0) {
      lines.push(truncate("Context drift: none", width));
    } else {
      lines.push(truncate(`Context drift: ${missing.length} missing • ${extra.length} extra`, width));
    }

    if (missing.length > 0) {
      lines.push(truncate(`Missing: ${missing.slice(0, 2).join(", ")}${missing.length > 2 ? " …" : ""}`, width));
    }
    if (extra.length > 0) {
      lines.push(truncate(`Extra: ${extra.slice(0, 2).join(", ")}${extra.length > 2 ? " …" : ""}`, width));
    }
  }

  if (story.failureReason) {
    lines.push("");
    lines.push(truncate(`Failure: ${story.failureReason}`, width));
  }

  if (story.startedAt) {
    lines.push(truncate(`Started: ${timeAgo(story.startedAt)}`, width));
  }
  if (story.finishedAt) {
    lines.push(truncate(`Finished: ${timeAgo(story.finishedAt)}`, width));
  }
  if (story.reroute) {
    lines.push("");
    lines.push(truncate(`Rerouted ${story.reroute.fromEngine} → ${story.reroute.toEngine}`, width));
    for (const line of wrapSimple(story.reroute.reason, width)) {
      lines.push(truncate(line, width));
    }
  }

  const storyDecisions = (runState?.decisions ?? []).filter((decision) => decision.storyId === story.id).slice(-4);
  if (storyDecisions.length > 0) {
    lines.push("");
    lines.push("Recent decisions:");
    for (const decision of storyDecisions) {
      lines.push(truncate(`- ${decision.type} • ${timeAgo(decision.timestamp)}`, width));
      for (const detail of wrapSimple(decision.description, Math.max(16, width - 2))) {
        lines.push(truncate(`  ${detail}`, width));
      }
    }
  }

  return lines;
}

function buildRunPane(
  payload: RunPayload | null,
  workspaceLabel: string,
  stories: StoryView[],
  waves: StoryView[][],
  width: number,
  workspaceRuns: RunListItem[] = [],
  workspaceRunsError: string | null = null,
): string[] {
  const lines: string[] = ["Run summary", ""];

  if (!payload) {
    lines.push("Loading run metadata...");
    return lines;
  }

  const counts = countStatuses(stories);
  const decisions = payload.runState?.decisions?.slice(-3) ?? [];
  const startedAt = payload.run.started_at ? timeAgo(payload.run.started_at) : "unknown";
  const finishedAt = payload.run.finished_at ? timeAgo(payload.run.finished_at) : "still active";
  const currentRunIndex = workspaceRuns.findIndex((item) => item.id === payload.run.id);
  const newerRun = currentRunIndex > 0 ? workspaceRuns[currentRunIndex - 1] : undefined;
  const olderRun = currentRunIndex >= 0 ? workspaceRuns[currentRunIndex + 1] : undefined;
  const failedStories = stories.filter((story) => normalizeStatus(story.status) === "failed");
  const queuedStories = stories.filter((story) => normalizeStatus(story.status) === "queued");
  const waitingStories = stories.filter((story) => {
    const status = normalizeStatus(story.status);
    return status === "pending" || status === "queued";
  });
  const readyStories = waitingStories.filter((story) => isStoryReady(story, stories));
  const blockedStories = waitingStories.filter((story) => !isStoryReady(story, stories) && story.dependsOn.length > 0);
  const activeWave = findActiveWave(waves);
  const activeWaveSummary = activeWave ? summarizeWaveProgress(activeWave.stories) : null;

  lines.push(truncate(`Spec: ${extractSpecSlug(payload.run.spec_path)}`, width));
  lines.push(truncate(`Workspace: ${workspaceLabel}`, width));
  lines.push(truncate(`Status: ${formatStatus(payload.run.status)}`, width));
  lines.push(truncate(`Started: ${startedAt} • Finished: ${finishedAt}`, width));
  lines.push(truncate(`Stories: ${stories.length} total • ${counts.get("running") ?? 0} running • ${counts.get("passed") ?? 0} passed • ${counts.get("failed") ?? 0} failed`, width));
  lines.push(truncate(`Tokens: in ${formatTokens(payload.tokenSummary?.inputTokens)} • out ${formatTokens(payload.tokenSummary?.outputTokens)} • ${formatCurrency(payload.tokenSummary?.totalCostUsd)}`, width));
  lines.push(truncate(`Model: ${payload.agentModel || payload.run.agent_model || payload.specModel || "auto"}`, width));
  lines.push(truncate(`Branch: ${payload.branchName || "n/a"}`, width));
  lines.push(truncate(`Worktree: ${payload.worktreePath || "n/a"}`, width));

  if (payload.run.queue_position != null) {
    lines.push(truncate(`Queue position: ${payload.run.queue_position}`, width));
  }
  if (payload.run.merge_status) {
    lines.push(truncate(`Merge status: ${payload.run.merge_status}`, width));
  }
  if (payload.runState?.currentStory) {
    lines.push(truncate(`Current story: ${payload.runState.currentStory}`, width));
  }
  if (payload.runState?.resumedFromStory) {
    lines.push(truncate(`Resumed from: ${payload.runState.resumedFromStory}`, width));
  }
  if (activeWave && activeWaveSummary) {
    lines.push(
      truncate(
        `Active wave: ${activeWave.index + 1}/${Math.max(1, waves.length)} • ${activeWaveSummary.done}/${activeWaveSummary.total} done • ${activeWaveSummary.running} running • ${activeWaveSummary.failed} failed • ${activeWaveSummary.pending} pending`,
        width,
      ),
    );
  }
  lines.push(truncate(`Pipeline: ${queuedStories.length} queued • ${readyStories.length} ready • ${blockedStories.length} blocked`, width));
  if (workspaceRunsError) {
    lines.push(truncate(`Workspace run history unavailable: ${workspaceRunsError}`, width));
  } else if (workspaceRuns.length > 0) {
    lines.push(truncate(`Workspace runs: ${workspaceRuns.length} loaded`, width));
    lines.push(truncate(`Newer: ${summarizeAdjacentRun(newerRun)}`, width));
    lines.push(truncate(`Older: ${summarizeAdjacentRun(olderRun)}`, width));

    const recentRuns = workspaceRuns.slice(0, 6);
    if (recentRuns.length > 0) {
      lines.push("");
      lines.push("Recent workspace runs:");
      recentRuns.forEach((recentRun, recentIndex) => {
        const marker = recentRun.id === payload.run.id ? ">" : " ";
        const started = recentRun.started_at ? timeAgo(recentRun.started_at) : "unknown";
        const quickKey = recentIndex < 6 ? `${recentIndex + 1} ` : "";
        lines.push(
          truncate(
            `${marker} ${quickKey}${statusIcon(recentRun.status)} ${recentRun.id} • ${extractSpecSlug(recentRun.spec_path)} • ${formatStatus(recentRun.status)} • ${started}`,
            width,
          ),
        );
      });
    }
  }
  if (failedStories.length > 0) {
    lines.push("");
    lines.push("Failures:");
    for (const story of failedStories.slice(0, 4)) {
      lines.push(truncate(`- ${story.id}${story.failureReason ? ` • ${story.failureReason}` : ""}`, width));
    }
    if (failedStories.length > 4) {
      lines.push(truncate(`… ${failedStories.length - 4} more failed stories`, width));
    }
  }
  if (blockedStories.length > 0 || readyStories.length > 0) {
    lines.push("");
    lines.push("Next up:");
    for (const story of readyStories.slice(0, 2)) {
      lines.push(truncate(`- ready ${story.id}`, width));
    }
    for (const story of blockedStories.slice(0, 2)) {
      lines.push(truncate(`- blocked ${story.id} • waits ${formatList(story.dependsOn)}`, width));
    }
  }
  if (activeWave?.stories.length) {
    const waitingInWave = activeWave.stories.filter((story) => {
      const normalized = normalizeStatus(story.status);
      return normalized === "pending" || normalized === "queued";
    });
    const runningInWave = activeWave.stories.filter((story) => normalizeStatus(story.status) === "running");

    lines.push("");
    lines.push(`Wave ${activeWave.index + 1} focus:`);
    for (const story of runningInWave.slice(0, 2)) {
      lines.push(truncate(`- running ${story.id}`, width));
    }
    for (const story of waitingInWave.slice(0, 3)) {
      const dependencyNote = story.dependsOn.length > 0 ? ` • waits ${formatList(story.dependsOn)}` : "";
      lines.push(truncate(`- waiting ${story.id}${dependencyNote}`, width));
    }
  }
  if (payload.run.summary) {
    lines.push("");
    lines.push("Summary:");
    for (const line of wrapSimple(payload.run.summary, width)) {
      lines.push(truncate(line, width));
    }
  }
  if (decisions.length > 0) {
    lines.push("");
    lines.push("Recent decisions:");
    for (const decision of decisions) {
      lines.push(truncate(`- ${decision.storyId}: ${decision.type}`, width));
      for (const line of wrapSimple(decision.description, Math.max(16, width - 2))) {
        lines.push(truncate(`  ${line}`, width));
      }
    }
  }

  return lines;
}

function isRetryableRun(status: RunStatus): boolean {
  const normalized = normalizeStatus(status);
  return normalized === "failed" || normalized === "done" || normalized === "partial_failure";
}

function isPausableRun(status: RunStatus): boolean {
  return normalizeStatus(status) === "running";
}

function isResumableRun(status: RunStatus): boolean {
  return normalizeStatus(status) === "paused";
}

function isCancellableRun(status: RunStatus): boolean {
  const normalized = normalizeStatus(status);
  return normalized === "queued" || normalized === "running" || normalized === "paused";
}

function buildEventsPane(payload: RunPayload | null, stories: StoryView[], width: number): string[] {
  const lines: string[] = ["Run events", ""];

  if (!payload) {
    lines.push("Loading orchestration events...");
    return lines;
  }

  const currentStoryId = payload.runState?.currentStory ?? null;
  const currentStory = currentStoryId ? stories.find((story) => story.id === currentStoryId) : undefined;
  const failedStories = stories.filter((story) => normalizeStatus(story.status) === "failed");
  const skippedStories = stories.filter((story) => normalizeStatus(story.status) === "skipped");
  const resumedFrom = payload.runState?.resumedFromStory;

  lines.push(truncate(`Current: ${currentStory?.id ?? currentStoryId ?? "none"}`, width));
  if (currentStory?.title) {
    lines.push(truncate(`Focus: ${currentStory.title}`, width));
  }
  lines.push(truncate(`Failures: ${failedStories.length} • Skipped: ${skippedStories.length}`, width));
  if (resumedFrom) {
    lines.push(truncate(`Resumed from: ${resumedFrom}`, width));
  }

  if (failedStories.length > 0) {
    lines.push("");
    lines.push("Failure queue:");
    for (const story of failedStories.slice(0, 4)) {
      lines.push(truncate(`- ${story.id}${story.failureReason ? ` • ${story.failureReason}` : ""}`, width));
    }
  }

  const decisions = payload.runState?.decisions ?? [];
  if (decisions.length === 0) {
    lines.push("");
    lines.push("No orchestration decisions recorded yet.");
    return lines;
  }

  lines.push("");
  lines.push("Recent decisions:");
  for (const decision of decisions.slice(-8).reverse()) {
    const story = stories.find((item) => item.id === decision.storyId);
    lines.push(truncate(`${timeAgo(decision.timestamp)} • ${decision.storyId} • ${decision.type}`, width));
    if (story?.title && story.title !== decision.storyId) {
      lines.push(truncate(`  ${story.title}`, width));
    }
    for (const detail of wrapSimple(decision.description, Math.max(16, width - 2)).slice(0, 3)) {
      lines.push(truncate(`  ${detail}`, width));
    }
  }

  return lines;
}

function buildLogPane(logLines: string[], logError: string | null, width: number): string[] {
  const lines: string[] = ["Run log", ""];

  if (logError) {
    lines.push(truncate(logError, width));
    return lines;
  }

  if (logLines.length === 0) {
    lines.push("No run log is available yet.");
    return lines;
  }

  for (const line of logLines.slice(-18)) {
    lines.push(truncate(line, width));
  }

  return lines;
}

function buildCommitsPane(commits: RunCommit[], branchName: string | null, commitsError: string | null, width: number): string[] {
  const lines: string[] = ["Run commits", ""];

  if (branchName) {
    lines.push(truncate(`Branch: ${branchName}`, width));
    lines.push("");
  }

  if (commitsError) {
    lines.push(truncate(commitsError, width));
    return lines;
  }

  if (commits.length === 0) {
    lines.push("No run-specific commits detected yet.");
    return lines;
  }

  for (const commit of commits.slice(0, 8)) {
    lines.push(truncate(`${commit.sha.slice(0, 7)}  ${commit.message}`, width));
    lines.push(truncate(`   ${commit.author} • ${timeAgo(commit.date)}`, width));
  }

  return lines;
}

function canRetryMerge(payload: RunPayload | null): boolean {
  return payload?.run.merge_status === "failed";
}

function sortWorkspaceRuns(items: RunListItem[]): RunListItem[] {
  return [...items].sort((left, right) => right.id - left.id);
}

function summarizeAdjacentRun(run: RunListItem | undefined): string {
  if (!run) {
    return "n/a";
  }
  return `${run.id} (${formatStatus(run.status)} • ${extractSpecSlug(run.spec_path)})`;
}

function isRetryableStory(story: StoryView | undefined): boolean {
  if (!story) {
    return false;
  }
  const status = normalizeStatus(story.status);
  return status === "failed" || status === "skipped";
}

function getRefreshIntervalMs(payload: RunPayload | null, pane: Pane): number {
  const status = normalizeStatus(payload?.run.status);

  if (status === "running" || status === "retrying") {
    return pane === "output" || pane === "events" || pane === "log" ? 1_500 : 2_500;
  }

  if (status === "queued" || status === "paused" || status === "cancelling") {
    return 4_000;
  }

  return 8_000;
}

export async function openRunView(
  ctx: ExtensionCommandContext,
  _pi: ExtensionAPI,
  initialRunId: number,
  baseUrl: string,
  token?: string,
): Promise<void> {
  if (!ctx.ui.custom) {
    notify(ctx.ui, "Pi custom UI is unavailable in this session. Use /rorca-tui as fallback.", "warning");
    return;
  }

  await ctx.ui.custom<void>((tui, _theme, _keybindings, done) => {
    let mounted = true;
    const publishStatus = (nextStatus: string | undefined) => {
      if (typeof ctx.ui.setStatus !== "function") {
        return;
      }

      try {
        ctx.ui.setStatus(RUN_VIEW_STATUS_ID, nextStatus);
      } catch {
        // Status publishing is opportunistic.
      }
    };
    let busy = true;
    let runId = initialRunId;
    let workspaceLabel = "Loading workspace…";
    let payload: RunPayload | null = null;
    let collection: StoryCollection = { stories: [], waves: [] };
    let selectedStoryId: string | null = null;
    let selectedOutput: StoryOutputPayload | null = null;
    let selectedOutputError: string | null = null;
    let runLogLines: string[] = [];
    let runLogError: string | null = null;
    let runCommits: RunCommit[] = [];
    let runCommitsBranchName: string | null = null;
    let runCommitsError: string | null = null;
    let workspaceRuns: RunListItem[] = [];
    let workspaceRunsError: string | null = null;
    let pane: Pane = "output";
    let statusLine = `Loading run ${runId}…`;
    let refreshTimer: NodeJS.Timeout | undefined;
    let resolvedWorkspaceId: string | null = null;
    let refreshVersion = 0;

    const requestRender = () => {
      if (mounted) {
        publishStatus(statusLine);
        tui.requestRender();
      }
    };

    const resolveWorkspaceLabel = async (workspaceId: string | number | undefined) => {
      const nextId = workspaceId == null ? null : String(workspaceId);
      if (!nextId || nextId === resolvedWorkspaceId) {
        return;
      }

      try {
        const workspace = await resolveWorkspace(baseUrl, token, nextId);
        resolvedWorkspaceId = workspace.id;
        workspaceLabel = workspace.label;
      } catch {
        resolvedWorkspaceId = nextId;
        workspaceLabel = nextId;
      }
    };

    const refreshSelectedOutput = async (targetRunId: number, version: number) => {
      const selected = collection.stories.find((story) => story.id === selectedStoryId);
      if (!selected) {
        if (mounted && version === refreshVersion && targetRunId === runId) {
          selectedOutput = null;
          selectedOutputError = null;
        }
        return;
      }

      try {
        const nextOutput = await apiFetchJson<StoryOutputPayload>(
          baseUrl,
          `/api/pipeline/runs/${targetRunId}/stories/${encodeURIComponent(selected.id)}/output?lines=100`,
          { token },
        );
        if (mounted && version === refreshVersion && targetRunId === runId) {
          selectedOutput = nextOutput;
          selectedOutputError = null;
        }
      } catch (error) {
        const apiError = error as ApiError;
        if (!mounted || version !== refreshVersion || targetRunId !== runId) {
          return;
        }
        selectedOutput = null;
        selectedOutputError =
          apiError.status === 404
            ? null
            : `Story output unavailable: ${error instanceof Error ? error.message : String(error)}`;
      }
    };

    const refreshRunLog = async (targetRunId: number, version: number) => {
      try {
        const text = await apiFetchText(baseUrl, `/api/pipeline/runs/${targetRunId}/log`, { token });
        if (mounted && version === refreshVersion && targetRunId === runId) {
          runLogLines = text.split(/\r?\n/);
          runLogError = null;
        }
      } catch (error) {
        const apiError = error as ApiError;
        if (!mounted || version !== refreshVersion || targetRunId !== runId) {
          return;
        }
        runLogLines = [];
        runLogError = apiError.status === 404 ? "Run log not available yet." : `Run log unavailable: ${error instanceof Error ? error.message : String(error)}`;
      }
    };

    const refreshRunCommits = async (targetRunId: number, version: number) => {
      try {
        const response = await apiFetchJson<RunCommitsPayload>(baseUrl, `/api/pipeline/runs/${targetRunId}/commits`, { token });
        if (mounted && version === refreshVersion && targetRunId === runId) {
          runCommits = response.commits ?? [];
          runCommitsBranchName = response.branchName ?? null;
          runCommitsError = null;
        }
      } catch (error) {
        const apiError = error as ApiError;
        if (!mounted || version !== refreshVersion || targetRunId !== runId) {
          return;
        }
        runCommits = [];
        runCommitsBranchName = null;
        runCommitsError = apiError.status === 404 ? "Run commits are not available for this run." : `Run commits unavailable: ${error instanceof Error ? error.message : String(error)}`;
      }
    };

    const refreshWorkspaceRuns = async (workspaceId: string | number | undefined, targetRunId: number, version: number) => {
      if (workspaceId == null) {
        if (mounted && version === refreshVersion && targetRunId === runId) {
          workspaceRuns = [];
          workspaceRunsError = null;
        }
        return;
      }

      try {
        const response = await apiFetchJson<RunListPayload>(
          baseUrl,
          `/api/pipeline/runs?workspaceId=${encodeURIComponent(String(workspaceId))}&limit=100`,
          { token },
        );

        if (mounted && version === refreshVersion && targetRunId === runId) {
          workspaceRuns = sortWorkspaceRuns(response.items ?? []);
          workspaceRunsError = null;
        }
      } catch (error) {
        if (!mounted || version !== refreshVersion || targetRunId !== runId) {
          return;
        }
        workspaceRuns = [];
        workspaceRunsError = error instanceof Error ? error.message : String(error);
      }
    };

    const syncRun = async () => {
      const targetRunId = runId;
      const version = ++refreshVersion;
      const nextPayload = await apiFetchJson<RunPayload>(baseUrl, `/api/pipeline/runs/${targetRunId}`, { token });
      await resolveWorkspaceLabel(nextPayload.run.workspace_id);
      await refreshWorkspaceRuns(nextPayload.run.workspace_id, targetRunId, version);
      if (!mounted || version !== refreshVersion || targetRunId !== runId) {
        return;
      }
      payload = nextPayload;
      collection = buildStories(nextPayload);
      selectedStoryId = chooseStoryId(collection.stories, selectedStoryId ?? nextPayload.runState?.currentStory ?? null);
      await refreshSelectedOutput(targetRunId, version);
      if (pane === "log") {
        await refreshRunLog(targetRunId, version);
      }
      if (pane === "commits") {
        await refreshRunCommits(targetRunId, version);
      }
      if (!mounted || version !== refreshVersion || targetRunId !== runId) {
        return;
      }
      const counts = countStatuses(collection.stories);
      statusLine = `Run ${targetRunId} • ${formatStatus(nextPayload.run.status)} • ${counts.get("running") ?? 0} running • ${counts.get("passed") ?? 0} passed • ${counts.get("failed") ?? 0} failed`;
      publishStatus(statusLine);
    };

    const runAction = (label: string, action: () => Promise<void>) => {
      if (busy) {
        return;
      }

      busy = true;
      statusLine = label;
      requestRender();

      void (async () => {
        try {
          await action();
          await syncRun();
        } catch (error) {
          const message = error instanceof Error ? error.message : String(error);
          statusLine = `Error: ${message}`;
          notify(ctx.ui, message, "error");
        } finally {
          busy = false;
          requestRender();
        }
      })();
    };

    const scheduleRefresh = () => {
      if (!mounted) {
        return;
      }
      refreshTimer = setTimeout(() => {
        if (!mounted || busy) {
          scheduleRefresh();
          return;
        }
        void syncRun().then(requestRender).catch((error) => {
          const message = error instanceof Error ? error.message : String(error);
          if (!mounted) {
            return;
          }
          statusLine = `Refresh failed: ${message}`;
          requestRender();
        }).finally(() => {
          scheduleRefresh();
        });
      }, getRefreshIntervalMs(payload, pane));
    };

    const close = () => {
      mounted = false;
      refreshVersion += 1;
      if (refreshTimer) {
        clearTimeout(refreshTimer);
      }
      publishStatus(undefined);
      done();
    };

    const focusStory = (nextStory: StoryView | undefined, statusMessage: string) => {
      if (!nextStory || nextStory.id === selectedStoryId) {
        return;
      }

      selectedStoryId = nextStory.id;
      statusLine = statusMessage;
      requestRender();

      const version = refreshVersion;
      const targetRunId = runId;
      void refreshSelectedOutput(targetRunId, version).then(requestRender).catch((error) => {
        const message = error instanceof Error ? error.message : String(error);
        if (!mounted || version !== refreshVersion || targetRunId !== runId) {
          return;
        }
        statusLine = `Output refresh failed: ${message}`;
        requestRender();
      });
    };

    const selectStory = (delta: number) => {
      const currentIndex = Math.max(0, collection.stories.findIndex((story) => story.id === selectedStoryId));
      const nextIndex = Math.max(0, Math.min(collection.stories.length - 1, currentIndex + delta));
      focusStory(collection.stories[nextIndex], `Focused ${collection.stories[nextIndex]?.id ?? "story"}`);
    };

    const focusCurrentStory = () => {
      const nextStory =
        collection.stories.find((story) => story.id === payload?.runState?.currentStory) ??
        collection.stories.find((story) => normalizeStatus(story.status) === "running");

      if (!nextStory) {
        statusLine = "No currently running story.";
        requestRender();
        return;
      }

      focusStory(nextStory, `Focused active story ${nextStory.id}`);
    };

    const focusNextMatchingStory = (
      candidateStories: StoryView[],
      emptyMessage: string,
      statusMessagePrefix: string,
    ) => {
      if (candidateStories.length === 0) {
        statusLine = emptyMessage;
        requestRender();
        return;
      }

      const currentIndex = candidateStories.findIndex((story) => story.id === selectedStoryId);
      const nextStory = candidateStories[(currentIndex + 1 + candidateStories.length) % candidateStories.length];
      focusStory(nextStory, `${statusMessagePrefix} ${nextStory?.id ?? "story"}`);
    };

    const focusNextFailedStory = () => {
      focusNextMatchingStory(
        collection.stories.filter((story) => normalizeStatus(story.status) === "failed"),
        "No failed stories in this run.",
        "Focused failed story",
      );
    };

    const focusNextReadyStory = () => {
      focusNextMatchingStory(
        collection.stories.filter((story) => isStoryReady(story, collection.stories)),
        "No ready stories in this run.",
        "Focused ready story",
      );
    };

    const focusNextBlockedStory = () => {
      focusNextMatchingStory(
        collection.stories.filter((story) => {
          const status = normalizeStatus(story.status);
          return (status === "pending" || status === "queued") && !isStoryReady(story, collection.stories) && story.dependsOn.length > 0;
        }),
        "No blocked stories in this run.",
        "Focused blocked story",
      );
    };

    const focusWave = (waveIndex: number) => {
      const wave = collection.waves[waveIndex];
      if (!wave || wave.length === 0) {
        statusLine = "No stories are available in that wave.";
        requestRender();
        return;
      }

      const nextStory =
        wave.find((story) => story.id === payload?.runState?.currentStory) ??
        wave.find((story) => normalizeStatus(story.status) === "running") ??
        wave.find((story) => normalizeStatus(story.status) === "failed") ??
        wave.find((story) => {
          const status = normalizeStatus(story.status);
          return status === "pending" || status === "queued";
        }) ??
        wave[0];

      focusStory(nextStory, `Focused wave ${waveIndex + 1} • ${nextStory?.id ?? "story"}`);
    };

    const focusActiveWave = () => {
      const activeWave = findActiveWave(collection.waves);
      if (!activeWave) {
        statusLine = "No wave data is available for this run.";
        requestRender();
        return;
      }

      focusWave(activeWave.index);
    };

    const focusAdjacentWave = (delta: number) => {
      if (collection.waves.length === 0) {
        statusLine = "No wave data is available for this run.";
        requestRender();
        return;
      }

      const currentWaveIndex = Math.max(
        0,
        collection.waves.findIndex((wave) => wave.some((story) => story.id === selectedStoryId)),
      );
      const nextWaveIndex = Math.max(0, Math.min(collection.waves.length - 1, currentWaveIndex + delta));
      if (nextWaveIndex === currentWaveIndex && collection.waves.length > 1) {
        statusLine = delta > 0 ? "Already on the last wave." : "Already on the first wave.";
        requestRender();
        return;
      }

      focusWave(nextWaveIndex);
    };

    const setPane = (nextPane: Pane) => {
      pane = nextPane;
      statusLine = `Pane: ${pane}`;
      requestRender();
      const version = refreshVersion;
      const targetRunId = runId;
      if (pane === "log") {
        void refreshRunLog(targetRunId, version)
          .then(requestRender)
          .catch((error) => {
            const message = error instanceof Error ? error.message : String(error);
            if (!mounted || version !== refreshVersion || targetRunId !== runId) {
              return;
            }
            runLogLines = [];
            runLogError = `Run log unavailable: ${message}`;
            statusLine = `Run log unavailable: ${message}`;
            requestRender();
          });
      }
      if (pane === "commits") {
        void refreshRunCommits(targetRunId, version)
          .then(requestRender)
          .catch((error) => {
            const message = error instanceof Error ? error.message : String(error);
            if (!mounted || version !== refreshVersion || targetRunId !== runId) {
              return;
            }
            runCommits = [];
            runCommitsBranchName = null;
            runCommitsError = `Run commits unavailable: ${message}`;
