      if (!storyToRetry) {
        statusLine = "Focused story is unavailable.";
        requestRender();
        return;
      }

      runAction(`Retrying ${storyToRetry.id}…`, async () => {
        const confirmed =
          (await ctx.ui.confirm?.("Retry focused story", `Queue a retry for ${storyToRetry.id}?`)) ?? false;
