function buildHelpPane(payload: RunPayload | null, selectedStory: StoryView | undefined, width: number): string[] {
  const lines: string[] = ["Cockpit help", ""];
  const sections: HelpSection[] = [
    {
      title: "Navigation",
      items: [
        "j/k or ↑/↓ move story focus",
        "u jump to the active story",
        "x jump to the next failed story",
        "n jump to the next ready story",
        "b jump to the next blocked story",
        "a jump to the active wave",
        ", and . move between waves",
      ],
    },
    {
      title: "Panes",
      items: [
        "tab cycles panes",
        "o output • t story • v run",
        "e events • l log • g commits",
        "? toggle this help",
      ],
    },
    {
      title: "Run history",
      items: [
        "[ older workspace run",
        "] newer workspace run",
        "1-6 jump to a recent workspace run",
        "r refresh now",
      ],
    },
    {
      title: "Actions",
      items: [
        payload && isPausableRun(payload.run.status)
          ? "p pause the current run"
          : payload && isResumableRun(payload.run.status)
            ? "p resume the paused run"
            : "p pause/resume when supported",
        payload && isCancellableRun(payload.run.status) ? "c cancel the current run" : "c cancel when the run is active",
        payload && isRetryableRun(payload.run.status) ? "f retry all failed/skipped stories" : "f retry failed stories when available",
        isRetryableStory(selectedStory) ? "s retry the focused failed/skipped story" : "s retry the focused story when it failed",
        canRetryMerge(payload) ? "m retry the failed auto-merge" : "m retry merge when auto-merge failed",
        "q or esc close the cockpit",
      ],
    },
  ];

  sections.forEach((section, sectionIndex) => {
    lines.push(truncate(section.title, width));
    section.items.forEach((item) => lines.push(truncate(`- ${item}`, width)));
    if (sectionIndex < sections.length - 1) {
      lines.push("");
    }
  });

  if (selectedStory) {
    lines.push("");
    lines.push(truncate(`Focused story: ${selectedStory.id} • ${formatStatus(selectedStory.status)}`, width));
  }

  return lines;
}

let pane: Pane = "output";
let showHelp = false;
let statusLine = `Loading run ${runId}…`;

